package shop

// Item is one line in the cart.
type Item struct {
	Cents int
	Qty   int
}

// Subtotal is the sum of the lines, in cents.
func Subtotal(items []Item) int {
	sum := 0
	for _, it := range items {
		sum += it.Cents * it.Qty
	}
	return sum
}

// Total applies the coupon, when the code names one, then adds tax at
// rateBPS, and returns the amount due in cents.
func Total(items []Item, code string, rateBPS int) int {
	sub := Subtotal(items)
	if bps, ok := Coupon(code); ok {
		sub -= Tax(sub, bps)
	}
	return sub + Tax(sub, rateBPS)
}

