package shop

var coupons = map[string]int{"SAVE10": 1000, "HALF": 5000}

// Coupon returns the discount in basis points for a code. The table is
// written in upper case, but customers type codes however they like and
// paste them with spaces around them.
func Coupon(code string) (int, bool) {
	v, ok := coupons[code]
	return v, ok
}

files.tax.go:
package shop

// Tax returns the tax on an amount in cents at a rate in basis points,
// rounded half up to the nearest cent.
func Tax(cents, bps int) int {
	return cents * bps / 10000
}

files.shop_test.go:
package shop

import "testing"

func TestSubtotal(t *testing.T) {
	if got := Subtotal([]Item{{Cents: 250, Qty: 2}, {Cents: 99, Qty: 1}}); got != 599 {
		t.Fatalf("Subtotal = %d, want 599", got)
	}
}

func TestTaxExact(t *testing.T) {
	if got := Tax(1000, 1000); got != 100 {
		t.Fatalf("Tax(1000, 1000) = %d, want 100", got)
	}
}

func TestTaxRoundsHalfUp(t *testing.T) {
	if got := Tax(1999, 875); got != 175 {
		t.Fatalf("Tax(1999, 875) = %d, want 175", got)
	}
}

func TestCouponExact(t *testing.T) {
	if bps, ok := Coupon("SAVE10"); !ok || bps != 1000 {
		t.Fatalf("Coupon(SAVE10) = %d, %v", bps, ok)
	}
}

func TestCouponIsCaseAndSpaceInsensitive(t *testing.T) {
	if bps, ok := Coupon(" half "); !ok || bps != 5000 {
		t.Fatalf("Coupon(\" half \") = %d, %v", bps, ok)
	}
}

func TestTotal(t *testing.T) {
	if got := Total([]Item{{Cents: 1000, Qty: 1}}, "SAVE10", 1000); got != 990 {
		t.Fatalf("Total = %d, want 990", got)
	}
}

