func TestHiddenTaxTable(t *testing.T) {
	for _, c := range []struct{ cents, bps, want int }{
		{0, 875, 0},
		{1, 5000, 1},
		{1, 4999, 0},
		{1999, 875, 175},
		{12345, 725, 895},
		{1000, 1000, 100},
	} {
		if got := Tax(c.cents, c.bps); got != c.want {
			t.Errorf("Tax(%d, %d) = %d, want %d", c.cents, c.bps, got, c.want)
		}
	}
}

func TestHiddenCouponLookup(t *testing.T) {
	for _, c := range []struct {
		in   string
		bps  int
		ok   bool
	}{
		{"SAVE10", 1000, true},
		{"save10", 1000, true},
		{"  Save10\t", 1000, true},
		{"HALF", 5000, true},
		{"nope", 0, false},
		{"", 0, false},
	} {
		bps, ok := Coupon(c.in)
		if ok != c.ok || (ok && bps != c.bps) {
			t.Errorf("Coupon(%q) = %d, %v; want %d, %v", c.in, bps, ok, c.bps, c.ok)
		}
	}
}

func TestHiddenTotalUsesBoth(t *testing.T) {
